// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // seed can be used to derive various states but the property must hold for all
        // We just call paused() on the reference and buggy versions.
        // Since the buggy version always returns true, the property is that
        // paused() must equal the actual _paused state. For the reference this holds,
        // for the buggy it fails when _paused is false.
        bool actualPaused = c.paused();
        // The reference returns the real _paused (initially false), bug returns true.
        // We assert that paused() equals the real storage value. In reference it is true,
        // in bug it is false when _paused is false. We can check this by toggling pause.
        // Since no external function exposes the raw storage, we rely on the fact that
        // the reference contract's paused() correctly reflects the internal state.
        // We can verify by pausing and checking.
        // First, check initial state: reference returns false, bug returns true.
        // The property: paused() == _paused. To make the assertion meaningful,
        // we call _pause() via owner to change state and observe.
        vm.prank(c.owner());
        c.pause();
        // After pause, actual paused should be true. Both return true.
        // Now unpause to make _paused false again.
        vm.prank(c.owner());
        c.unPause();
        // Now _paused is false. Reference paused() returns false, bug returns true.
        bool isPaused = c.paused();
        // The invariant: paused() must return false when contract is not paused.
        // We assert that isPaused is false (reference) while bug returns true.
        assertTrue(!isPaused);
    }
}
